Actionscript.script:
this._rotation = 0;
_root.gameworld._y += 5;
var 获取发射对象 = _root.gameworld[this.发射者名];
if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
   this.子弹威力 *= 1 + 获取发射对象.被动技能.轰炸专家.等级 * 0.02;
   this.友军伤害 = false;
}else{
	this.友军伤害 = true;
}

_root.gameworld._y -= 5;
if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
	this.子弹敌我属性值 = this.子弹敌我属性值;
}else{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
子弹威力 *= 0.6;

_root.gameworld._y += 3;
if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
   this.子弹敌我属性值 = this.子弹敌我属性值;
}else{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}

_root.gameworld._y -= 3;
if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
   this.子弹威力 *= 0.6 + 获取发射对象.被动技能.轰炸专家.等级 * 0.02;
	this.子弹敌我属性值 = this.子弹敌我属性值;
}else{
   this.子弹威力 *= 0.5;
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
   this.伤害类型 = "魔法";
   this.魔法伤害属性 = "能";

if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
	this.子弹敌我属性值 = this.子弹敌我属性值;
}else{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
   this.伤害类型 = "魔法";
   this.魔法伤害属性 = "热";

if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
	this.子弹敌我属性值 = this.子弹敌我属性值;
}else{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
   this.伤害类型 = "魔法";
   this.魔法伤害属性 = "波";

if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
	this.子弹敌我属性值 = this.子弹敌我属性值;
