if(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用)
{
    this.子弹威力 *= 0.03 + 0.2/获取发射对象.被动技能.轰炸专家.等级;
	this.子弹威力 = Math.min(this.子弹威力, 2000 + 5000 / 获取发射对象.被动技能.轰炸专家.等级);
	this.子弹敌我属性值 = !this.子弹敌我属性值;
	this.友军伤害 = true;
}else{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
   this.伤害类型 = "魔法";
   this.魔法伤害属性 = "冲";

if(!(获取发射对象.被动技能.轰炸专家 && 获取发射对象.被动技能.轰炸专家.启用))
{
	this.子弹敌我属性值 = !this.子弹敌我属性值;
}
